// Validate and normalize operational events for LysOps canonical event store
const items = $input.all();
const normalized = [];
const allowedCategories = new Set(['ACTION_REQUIRED', 'DECISION_REQUIRED', 'WAITING', 'FYI', 'IGNORE']);
const allowedStatuses = new Set(['OPEN', 'RESOLVED', 'DISMISSED']);
const now = new Date().toISOString();

for (const item of items) {
  const raw = item.json ?? {};

  // Support query action if requested
  if (raw.action === 'query') {
    normalized.push({
      _action: 'query',
      source: raw.source ? String(raw.source).toLowerCase() : null,
      category: raw.category ? String(raw.category).toUpperCase() : null,
      status: raw.status ? String(raw.status).toUpperCase() : null,
      since: raw.since || null,
      limit: Number(raw.limit) || 100
    });
    continue;
  }

  // Required field validation for upsert
  if (!raw.event_id || typeof raw.event_id !== 'string') {
    throw new Error('STATE-01 Validation Error: Missing or invalid required field "event_id"');
  }
  if (!raw.source || typeof raw.source !== 'string') {
    throw new Error(`STATE-01 Validation Error: Missing or invalid required field "source" for event ${raw.event_id}`);
  }
  if (!raw.event_type || typeof raw.event_type !== 'string') {
    throw new Error(`STATE-01 Validation Error: Missing or invalid required field "event_type" for event ${raw.event_id}`);
  }
  if (!raw.summary || typeof raw.summary !== 'string') {
    throw new Error(`STATE-01 Validation Error: Missing or invalid required field "summary" for event ${raw.event_id}`);
  }

  // Normalization & Privacy hygiene
  const category = allowedCategories.has(raw.category) ? raw.category : 'FYI';
  const status = allowedStatuses.has(raw.status) ? raw.status : 'OPEN';

  let priority = Number(raw.priority);
  if (!Number.isFinite(priority) || priority < 0 || priority > 1) {
    priority = category === 'ACTION_REQUIRED' ? 0.8 : (category === 'DECISION_REQUIRED' ? 0.7 : 0.4);
  }

  // Sanitize summary: trim, max 500 chars
  const cleanSummary = String(raw.summary).replace(/\s+/g, ' ').trim().slice(0, 500);

  // Filter metadata to prevent secrets/tokens/credentials
  const safeMetadata = {};
  if (raw.metadata && typeof raw.metadata === 'object' && !Array.isArray(raw.metadata)) {
    for (const [k, v] of Object.entries(raw.metadata)) {
      const lowerK = k.toLowerCase();
      if (lowerK.includes('token') || lowerK.includes('secret') || lowerK.includes('key') || lowerK.includes('pass') || lowerK.includes('auth')) {
        continue;
      }
      if (typeof v === 'string' && v.length > 500) {
        safeMetadata[k] = v.slice(0, 500);
      } else {
        safeMetadata[k] = v;
      }
    }
  }

  normalized.push({
    _action: 'upsert',
    event_id: raw.event_id.trim(),
    occurred_at: raw.occurred_at ? new Date(raw.occurred_at).toISOString() : now,
    ingested_at: raw.ingested_at ? new Date(raw.ingested_at).toISOString() : now,
    source: raw.source.trim().toLowerCase(),
    event_type: raw.event_type.trim().toLowerCase(),
    category,
    priority,
    summary: cleanSummary,
    status,
    source_ref: raw.source_ref ? String(raw.source_ref).slice(0, 100) : null,
    correlation_id: raw.correlation_id ? String(raw.correlation_id).slice(0, 100) : null,
    metadata: safeMetadata,
    metadata_json: JSON.stringify(safeMetadata),
    created_at: now
  });
}

return normalized.map(n => ({ json: n }));

const sqlite = require('node:sqlite');
const dbPath = '/data/lysops/lysops.db';
const db = new sqlite.DatabaseSync(dbPath);

// Ensure table and indexes exist
db.exec(`
  CREATE TABLE IF NOT EXISTS operational_events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    event_id TEXT NOT NULL UNIQUE,
    occurred_at TEXT NOT NULL,
    ingested_at TEXT NOT NULL,
    source TEXT NOT NULL,
    event_type TEXT NOT NULL,
    category TEXT,
    priority REAL,
    summary TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'OPEN',
    source_ref TEXT,
    correlation_id TEXT,
    metadata_json TEXT,
    created_at TEXT NOT NULL
  );
  CREATE INDEX IF NOT EXISTS idx_operational_events_occurred ON operational_events(occurred_at);
  CREATE INDEX IF NOT EXISTS idx_operational_events_source ON operational_events(source);
  CREATE INDEX IF NOT EXISTS idx_operational_events_category ON operational_events(category);
  CREATE INDEX IF NOT EXISTS idx_operational_events_status ON operational_events(status);
`);

const upsertStmt = db.prepare(`
  INSERT INTO operational_events (
    event_id, occurred_at, ingested_at, source, event_type,
    category, priority, summary, status, source_ref,
    correlation_id, metadata_json, created_at
  ) VALUES (
    ?, ?, ?, ?, ?,
    ?, ?, ?, ?, ?,
    ?, ?, ?
  )
  ON CONFLICT(event_id) DO UPDATE SET
    category = excluded.category,
    priority = excluded.priority,
    summary = excluded.summary,
    status = excluded.status,
    source_ref = excluded.source_ref,
    correlation_id = excluded.correlation_id,
    metadata_json = excluded.metadata_json;
`);

const selectStmt = db.prepare('SELECT * FROM operational_events WHERE event_id = ?');

const results = [];
const items = $input.all();

for (const item of items) {
  const e = item.json;
  if (e._action === 'query') {
    let sql = 'SELECT * FROM operational_events WHERE 1=1';
    const params = [];
    if (e.source) {
      sql += ' AND source = ?';
      params.push(e.source);
    }
    if (e.category) {
      sql += ' AND category = ?';
      params.push(e.category);
    }
    if (e.status) {
      sql += ' AND status = ?';
      params.push(e.status);
    }
    if (e.since) {
      sql += ' AND occurred_at >= ?';
      params.push(e.since);
    }
    sql += ' ORDER BY occurred_at DESC LIMIT ?';
    params.push(e.limit || 100);

    const rows = db.prepare(sql).all(...params);
    for (const r of rows) {
      let meta = {};
      try { meta = JSON.parse(r.metadata_json || '{}'); } catch (_) {}
      results.push({
        json: {
          id: r.id,
          event_id: r.event_id,
          occurred_at: r.occurred_at,
          ingested_at: r.ingested_at,
          source: r.source,
          event_type: r.event_type,
          category: r.category,
          priority: r.priority,
          summary: r.summary,
          status: r.status,
          source_ref: r.source_ref,
          correlation_id: r.correlation_id,
          metadata: meta,
          created_at: r.created_at
        }
      });
    }
  } else {
    upsertStmt.run(
      e.event_id, e.occurred_at, e.ingested_at, e.source, e.event_type,
      e.category, e.priority, e.summary, e.status, e.source_ref,
      e.correlation_id, e.metadata_json, e.created_at
    );

    const stored = selectStmt.get(e.event_id);
    let meta = {};
    try { meta = JSON.parse(stored.metadata_json || '{}'); } catch (_) {}

    results.push({
      json: {
        id: stored.id,
        event_id: stored.event_id,
        occurred_at: stored.occurred_at,
        ingested_at: stored.ingested_at,
        source: stored.source,
        event_type: stored.event_type,
        category: stored.category,
        priority: stored.priority,
        summary: stored.summary,
        status: stored.status,
        source_ref: stored.source_ref,
        correlation_id: stored.correlation_id,
        metadata: meta,
        created_at: stored.created_at
      }
    });
  }
}

return results;
